+.brand-name{font-weight:750;letter-spacing:.2px}
+
+.header-search{flex:1;display:flex;justify-content:center}
+.search{
+  width:min(620px,100%);
+  display:flex;align-items:center;gap:10px;
+  padding:10px 12px;
+  border-radius:999px;
+  background:rgba(255,255,255,.10);
+  border:1px solid rgba(255,255,255,.16)
+}
+.search svg{opacity:.9}
+.search input{
+  width:100%;border:0;outline:0;background:transparent;
+  color:#fff;font-size:14px
+}
+.search input::placeholder{color:rgba(255,255,255,.72)}
+
+.nav{display:flex;gap:16px;align-items:center}
+.nav a{color:#fff;opacity:.92;font-weight:600}
+.nav a:hover{opacity:1;text-decoration:none}
+.nav .cta{padding:9px 12px;border-radius:999px;background:var(--amber);color:var(--navy)}
+.nav .cta:hover{filter:brightness(.98)}
+
+.menu-btn{
+  display:none;
+  width:42px;height:42px;border-radius:12px;
+  background:rgba(255,255,255,.10);
+  border:1px solid rgba(255,255,255,.18);
+  color:#fff
+}
+.menu-btn:focus{outline:2px solid rgba(254,172,50,.65);outline-offset:2px}
+
+.mobile-nav{
+  display:none;
+  padding:0 0 14px 0
+}
+.mobile-nav[hidden]{display:none}
+.mobile-nav a{
+  display:block;padding:12px 12px;border-radius:14px;
+  color:#fff;font-weight:650;opacity:.95
+}
+.mobile-nav a:hover{text-decoration:none;background:rgba(255,255,255,.08)}
+.mobile-nav .cta{background:rgba(254,172,50,.15);border:1px solid rgba(254,172,50,.35);color:#fff}
+
+/* Banner */
+.top-banner{background:linear-gradient(90deg, rgba(254,172,50,.18), rgba(254,172,50,.06));border-bottom:1px solid var(--border)}
+.banner-inner{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 0}
+.banner-inner strong{font-size:15px}
+.banner-inner a{color:var(--navy);font-weight:700}
+.banner-pill{display:inline-flex;gap:8px;align-items:center;padding:8px 10px;border-radius:999px;background:#fff;border:1px solid var(--border)}
+
+/* Page */
+main{padding:26px 0 46px 0}
+.page-title{font-size:32px;line-height:1.15;letter-spacing:-.6px;margin:0 0 10px 0}
+.page-subtitle{color:var(--muted);margin:0 0 18px 0}
+
+/* Featured */
+.featured{
+  display:grid;grid-template-columns:1.1fr .9fr;gap:18px;align-items:stretch;
+  margin:10px 0 18px
+}
+.featured-card{
+  position:relative;border-radius:var(--radius-lg);
+  overflow:hidden;
+  min-height:320px;
+  box-shadow:var(--shadow);
+  background:linear-gradient(135deg, rgba(10,10,35,.92), rgba(10,10,35,.72)),
+             radial-gradient(circle at 20% 10%, rgba(254,172,50,.35), transparent 50%),
+             radial-gradient(circle at 80% 80%, rgba(0,46,173,.35), transparent 55%);
+}
+.featured-card .featured-body{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;padding:18px}
+.tag-chip{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:6px 10px;border-radius:999px;
+  font-weight:750;font-size:12px;letter-spacing:.25px;
+  color:var(--navy);background:var(--amber)
+}
+.tag-chip.secondary{background:#fff;color:var(--navy);border:1px solid var(--border)}
+.featured-title{color:#fff;font-size:28px;line-height:1.18;margin:10px 0 12px 0;letter-spacing:-.4px}
+
+/* Article cards */
+.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin:10px 0 12px}
+.section-head h2{margin:0;font-size:18px;letter-spacing:-.2px}
+.section-head a{font-weight:650}
+
+.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
+.card{
+  background:#fff;border:1px solid var(--border);
+  border-radius:var(--radius-lg);
+  overflow:hidden;
+  box-shadow:0 1px 0 rgba(10,10,35,.03);
+  transition:transform .14s ease, box-shadow .14s ease, border-color .14s ease;
+}
+.card:hover{transform:translateY(-2px);box-shadow:var(--shadow-soft);border-color:rgba(10,10,35,.18)}
+.thumb{aspect-ratio:16/9;background:linear-gradient(135deg, rgba(0,46,173,.25), rgba(254,172,50,.28)),
+       radial-gradient(circle at 60% 20%, rgba(10,10,35,.18), transparent 55%);
+}
+.card-body{padding:14px 14px 12px}
+.card-title{margin:10px 0 12px;font-size:16px;line-height:1.25;letter-spacing:-.2px}
+.meta{display:flex;align-items:center;justify-content:space-between;gap:10px;color:var(--muted);font-size:13px}
+.author{display:flex;align-items:center;gap:10px;min-width:0}
+.avatar{
+  width:28px;height:28px;border-radius:999px;flex:0 0 auto;
+  background:linear-gradient(135deg, rgba(254,172,50,.55), rgba(0,46,173,.35));
+  border:1px solid rgba(10,10,35,.12)
+}
+.author-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:160px}
+.time{white-space:nowrap}
+
+.load-more{margin:18px 0 0;display:flex;justify-content:center}
+.btn{
+  appearance:none;border:0;cursor:pointer;
+  border-radius:14px;padding:12px 14px;
+  font-weight:750;letter-spacing:.1px
+}
+.btn-primary{background:var(--navy);color:#fff}
+.btn-primary:hover{filter:brightness(1.05)}
+.btn-outline{background:#fff;border:1px solid var(--border);color:var(--navy)}
+.btn-outline:hover{border-color:rgba(10,10,35,.2)}
+
+/* Learn page blocks */
+.panel{
+  background:var(--surface);
+  border:1px solid var(--border);
+  border-radius:var(--radius-lg);
+  padding:18px
+}
+.two-col{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}
+.list{display:grid;gap:10px;margin:0;padding:0;list-style:none}
+.item{
+  display:flex;gap:12px;align-items:flex-start;
+  padding:12px 12px;border-radius:14px;
+  background:#fff;border:1px solid var(--border)
+}
+.icon{
+  width:38px;height:38px;border-radius:14px;
+  display:grid;place-items:center;
+  background:rgba(254,172,50,.14);
+  border:1px solid rgba(254,172,50,.30);
+  color:var(--navy);font-weight:850
+}
+.item h3{margin:0;font-size:15px;line-height:1.25}
+.item p{margin:4px 0 0;color:var(--muted);font-size:13px}
+
+/* Donate */
+.donate-hero{display:grid;grid-template-columns:1.1fr .9fr;gap:16px;align-items:start;margin:10px 0 18px}
+.impact-card{background:var(--navy);color:#fff;border-radius:var(--radius-lg);padding:18px;box-shadow:var(--shadow)}
+.impact-card p{color:rgba(255,255,255,.86);margin:10px 0 0}
+.donation-box{background:#fff;border:1px solid var(--border);border-radius:var(--radius-lg);padding:16px;box-shadow:0 1px 0 rgba(10,10,35,.03)}
+.tabs{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:10px 0 12px}
+.tab{
+  width:100%;padding:11px 10px;border-radius:14px;
+  border:1px solid var(--border);background:#fff;
+  font-weight:800;color:var(--navy);cursor:pointer
+}
+.tab[aria-selected="true"]{background:rgba(254,172,50,.22);border-color:rgba(254,172,50,.55)}
+.donation-desc{margin:0 0 12px;color:var(--muted)}
+.donation-cta{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
+.subnote{color:var(--muted);font-size:13px;margin:10px 0 0}
+.subnote a{font-weight:650}
+
+.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
+.stat{background:#fff;border:1px solid var(--border);border-radius:var(--radius-lg);padding:14px}
+.stat strong{display:block;font-size:20px;letter-spacing:-.3px}
+.stat span{color:var(--muted);font-size:13px}
+
+/* FAQ accordion */
+.accordion{display:grid;gap:10px}
+.acc-item{border:1px solid var(--border);border-radius:var(--radius-lg);background:#fff;overflow:hidden}
+.acc-btn{
+  width:100%;text-align:left;cursor:pointer;
+  display:flex;align-items:center;justify-content:space-between;gap:12px;
+  padding:14px 14px;background:#fff;border:0;font-weight:750;color:var(--navy)
+}
+.acc-btn:focus{outline:2px solid rgba(0,46,173,.35);outline-offset:2px}
+.acc-panel{max-height:0;overflow:hidden;transition:max-height .24s ease;}
+.acc-panel .acc-content{padding:0 14px 14px;color:var(--muted)}
+.chev{transition:transform .22s ease;opacity:.75}
+.acc-item[data-open="true"] .chev{transform:rotate(180deg)}
+
+/* Tag page */
+.tag-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin:12px 0 14px}
+.tag-title{display:flex;align-items:baseline;gap:10px}
+.tag-title h1{margin:0;font-size:28px;letter-spacing:-.45px}
+.tag-title .count{color:var(--muted);font-weight:650}
+
+.pill-row{
+  display:flex;gap:10px;overflow:auto;padding:8px 0 2px;
+  scrollbar-width:thin
+}
+.tag-pill{
+  flex:0 0 auto;
+  display:inline-flex;gap:8px;align-items:center;
+  padding:10px 12px;border-radius:999px;
+  background:#fff;border:1px solid var(--border);
+  color:var(--navy);font-weight:750
+}
+.tag-pill span{color:var(--muted);font-weight:700}
+
+/* Footer */
+footer{border-top:1px solid var(--border);background:var(--surface)}
+.footer-inner{padding:26px 0}
+.footer-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:18px}
+.footer-inner p{margin:0;color:var(--muted)}
+.footer-links{display:flex;flex-wrap:wrap;gap:10px;margin-top:12px}
+.footer-links a{color:var(--navy);font-weight:650}
+.kicker{font-size:12px;letter-spacing:.18px;color:var(--muted);text-transform:uppercase}
+
+/* Responsive */
+@media (max-width: 980px){
+  .grid{grid-template-columns:repeat(2,1fr)}
+  .featured{grid-template-columns:1fr}
+  .donate-hero{grid-template-columns:1fr}
+  .two-col{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:1fr}
+  .stats{grid-template-columns:1fr}
+}
+
+@media (max-width: 760px){
+  .header-search{display:none}
+  .nav{display:none}
+  .menu-btn{display:inline-grid;place-items:center}
+  .mobile-nav{display:block}
+  .grid{grid-template-columns:1fr}
+  .page-title{font-size:28px}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto}
+  .acc-panel{transition:none}
+  .card{transition:none}
+}
+
*** End Patch
PATCH

