+
+  function els(sel, root = document) {
+    return Array.from(root.querySelectorAll(sel));
+  }
+
+  function safeId(str) {
+    return String(str).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
